193	// 编号重复时返回 ErrDuplicateID 且保留原记录。
194	func (s *Store) RegisterPart(id string, initialStock int) error {
195		if id == "" {
196			return fmt.Errorf("%w: part id must not be empty", ErrInvalidParam)
197		}
198		if initialStock < 0 {
199			return fmt.Errorf("%w: initial stock must be a non-negative integer", ErrInvalidParam)
200		}
201		s.mu.Lock()
202		defer s.mu.Unlock()
203		if _, ok := s.parts[id]; ok {
204			return fmt.Errorf("%w: part %q", ErrDuplicateID, id)
205		}
206		s.parts[id] = &Part{ID: id, Stock: initialStock}
207		return nil
208	}
209	
210	// SubmitRequest 提交保修请求，指定产品和故障代码。
211	// 编号重复时返回 ErrDuplicateID 且保留原记录。
212	func (s *Store) SubmitRequest(id, productID, faultCode string) error {
213		if id == "" {
214			return fmt.Errorf("%w: request id must not be empty", ErrInvalidParam)
215		}
216		if faultCode == "" {
217			return fmt.Errorf("%w: fault code must not be empty", ErrInvalidParam)
218		}
219		s.mu.Lock()
220		defer s.mu.Unlock()
221		if _, ok := s.requests[id]; ok {
222			return fmt.Errorf("%w: request %q", ErrDuplicateID, id)
223		}
224		s.requests[id] = &Request{ID: id, ProductID: productID, FaultCode: faultCode}
225		return nil
226	}
227	
228	// Product 返回指定编号的产品副本，不存在时返回 ErrNotFound。
229	func (s *Store) Product(id string) (Product, error) {
230		s.mu.Lock()
231		defer s.mu.Unlock()
232		p, ok := s.products[id]
233		if !ok {
234			return Product{}, fmt.Errorf("%w: product %q", ErrNotFound, id)
235		}
236		cp := *p
237		cp.ExcludedCodes = make(map[string]struct{}, len(p.ExcludedCodes))
238		for k := range p.ExcludedCodes {
239			cp.ExcludedCodes[k] = struct{}{}
240		}
241		return cp, nil
242	}
243	
244	// Part 返回指定编号的备件副本，不存在时返回 ErrNotFound。
245	func (s *Store) Part(id string) (Part, error) {
246		s.mu.Lock()
247		defer s.mu.Unlock()
248		p, ok := s.parts[id]
249		if !ok {
250			return Part{}, fmt.Errorf("%w: part %q", ErrNotFound, id)
251		}
252		return *p, nil
253	}
254	
255	// Request 返回指定编号的请求副本，不存在时返回 ErrNotFound。
256	func (s *Store) Request(id string) (Request, error) {
257		s.mu.Lock()
258		defer s.mu.Unlock()
259		r, ok := s.requests[id]
260		if !ok {
261			return Request{}, fmt.Errorf("%w: request %q", ErrNotFound, id)
262		}
263		return *r, nil
264	}
265	
266	// Commitment 返回指定编号的承诺副本，不存在时返回 ErrNotFound。
267	func (s *Store) Commitment(id string) (Commitment, error) {
268		s.mu.Lock()
269		defer s.mu.Unlock()
270		c, ok := s.commitments[id]
271		if !ok {
272			return Commitment{}, fmt.Errorf("%w: commitment %q", ErrNotFound, id)
273		}
274		return *c, nil
275	}
